def feats(x, degree=2, omega=None):
    from itertools import combinations_with_replacement
    a = [np.ones(len(x))]
    names = ['1']
    for d in range(1, degree + 1):
        for i in combinations_with_replacement(range(4), d):
            a.append(x[:, i].prod(axis=1))
            names.append(''.join((str(j) for j in i)))
    if omega is not None:
        a.extend([*np.sin(omega * x.T), *np.cos(omega * x.T)])
        names.extend([f'{f}{i}' for f in ('s', 'c') for i in range(4)])
    return (np.stack(a, axis=1), names)

def fit(X, y, robust=False):
    w = np.ones(len(y))
    for i in range(45 if robust else 1):
        b = np.linalg.lstsq(X * w[:, None], y * w[:, None], rcond=None)[0]
        r = np.linalg.norm(X @ b - y, axis=1)
        w = np.power(1 + (r / max(0.002, 0.7 * np.median(r))) ** 2, -0.5)
    return (b, r, w)

def _scalar_design(z):
    interaction = z[:, 0] * z[:, 2] + z[:, 1] * z[:, 3]
    return np.column_stack((z, interaction))

def _trajectory(x, target, x_test, t):
    from scipy.optimize import least_squares

    def basis(rates):
        return -np.expm1(-t[:, None] * rates)

    def residual(rates):
        b = basis(rates)
        return (b @ _fit(b, target.T) - target.T).ravel()
    rates = least_squares(residual, [0.4, 1.8], bounds=([0.01, 0.8], [0.8, 8.0])).x
    b = basis(rates)
    return x_test @ _fit(x, _fit(b, target.T).T) @ b.T
